"""Invoice export, plus the NORTHSTAR settlement export from 2026-09 (EXPORT-NS-1, FIN-SETTLEMENT-2)."""
import csv
import io
from datetime import datetime
from zoneinfo import ZoneInfo

SETTLEMENT_CUSTOMER = "NORTHSTAR"
SETTLEMENT_START_MONTH = "2026-09"
SETTLEMENT_TZ = ZoneInfo("America/New_York")
SETTLED_STATUSES = ("PAID", "REFUNDED")


def export_csv(rows, customer, month):
    if customer == SETTLEMENT_CUSTOMER and month >= SETTLEMENT_START_MONTH:
        return _settlement_csv(rows, customer, month)
    return _invoice_csv(rows, customer, month)


def _invoice_csv(rows, customer, month):
    stream = io.StringIO(newline="")
    writer = csv.writer(stream, lineterminator="\n")
    writer.writerow(["invoice_id", "amount_cents"])
    for row in rows:
        if row["customer"] == customer and row["invoice_at"][:7] == month:
            writer.writerow([row["invoice_id"], row["gross_cents"]])
    return stream.getvalue()


def _settlement_csv(rows, customer, month):
    records = []
    for row in rows:
        if row.get("customer") != customer:
            continue
        # PENDING, VOID and other statuses are ignored before settled_at is read.
        status = row.get("status")
        if status not in SETTLED_STATUSES:
            continue
        local_date = _local_settlement_date(row)
        if local_date.strftime("%Y-%m") != month:
            continue
        gross = _cents(row, "gross_cents")
        fee = _cents(row, "fee_cents")
        if row.get("currency") != "USD":
            raise ValueError(
                f"{row.get('invoice_id')}: currency {row.get('currency')!r} is not USD"
            )
        # Refunds return the gross amount only; processing fees are not returned.
        net = gross - fee if status == "PAID" else -gross
        records.append((local_date.isoformat(), row["invoice_id"], net))

    records.sort()
    stream = io.StringIO(newline="")
    writer = csv.writer(stream, lineterminator="\n")
    writer.writerow(["invoice_id", "settlement_date", "net_cents"])
    for settlement_date, invoice_id, net in records:
        writer.writerow([invoice_id, settlement_date, net])
    return stream.getvalue()


def _local_settlement_date(row):
    value = row.get("settled_at")
    if not isinstance(value, str) or not value:
        raise ValueError(f"{row.get('invoice_id')}: settled_at is missing")
    try:
        settled = datetime.fromisoformat(value)
    except ValueError:
        raise ValueError(f"{row.get('invoice_id')}: settled_at {value!r} is not ISO 8601")
    if settled.tzinfo is None or settled.utcoffset() is None:
        raise ValueError(f"{row.get('invoice_id')}: settled_at {value!r} has no UTC offset")
    return settled.astimezone(SETTLEMENT_TZ).date()


def _cents(row, field):
    value = row.get(field)
    if type(value) is not int or value < 0:
        raise ValueError(
            f"{row.get('invoice_id')}: {field} {value!r} is not a nonnegative integer"
        )
    return value
